import * as z from "zod/v4";
import { has } from "../../../channels/slack/agentic-posted.js";
import { MAX_REASON_CHARS } from "../../../channels/slack/agentic-signals.js";
import { defineTool } from "../../../tools.js";
const INVALID_ARGUMENTS_MESSAGE = "delete-message needs a ts this turn posted and a short reason.";
const FOREIGN_TS = "ts is not a message this turn posted";
const deleteMessage = defineTool({
    description: [
        "Delete a message this turn just posted that is wrong (duplicate, secret, wrong thread).",
        "ts is the one post-update returned. Never someone else's message.",
        "Never delete to clean up progress.",
        "The channel watching this turn deletes it.",
    ].join(" "),
    inputSchema: z.object({
        ts: z.string().trim().min(1, INVALID_ARGUMENTS_MESSAGE),
        reason: z
            .string()
            .trim()
            .min(1, INVALID_ARGUMENTS_MESSAGE)
            .max(MAX_REASON_CHARS, INVALID_ARGUMENTS_MESSAGE),
    }),
    execute: ({ ts, reason }, ctx) => {
        if (!has(ctx.session.id, ts)) {
            return FOREIGN_TS;
        }
        return { ts, reason };
    },
});
export default deleteMessage;
